section-header.content:
import type { HTMLAttributes, ReactNode } from "react";
import { SemanticContent } from "@clossys/designer/components";
import { mergeUiClasses as cx } from "@clossys/designer/components";

/** CardHeader/CardTitle/CardDescription/CardAction anatomy, adapted to a section heading. */
export interface SectionHeaderProps extends Omit<HTMLAttributes<HTMLDivElement>, "title"> {
  eyebrow?: ReactNode;
  title?: ReactNode;
  description?: ReactNode;
  actions?: ReactNode;
  stats?: ReactNode;
  level?: 1 | 2 | 3 | 4 | 5 | 6;
  density?: "compact" | "standard" | "display";
  align?: "start" | "center";
  ground?: "base" | "sunken" | "inverse";
  titleClassName?: string;
}

export function SectionHeader(props: SectionHeaderProps) {
  const { eyebrow, title, description, actions, stats, level = 2, density = "compact", align = "start", ground = "base", titleClassName, className, ...rest } = props;
  const heading = `h${level}` as "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
  const centered = align === "center";
  const inverse = ground === "inverse";
  const titleSize = density === "display" ? "text-display-m tablet:text-display-l" : density === "standard" ? "text-h2" : "text-h3";
  return (
    <SemanticContent as="div" {...rest} data-ds-layer="sections" data-ds-leaf="sections.section-header" data-ds-fill="shadcn@aria/sections.section-header" data-slot="card-header" className={cx("flex flex-col gap-md", centered ? "items-center text-center" : "tablet:flex-row tablet:items-start tablet:justify-between", className)}>
      <SemanticContent as="div" className={["flex min-w-0 flex-col gap-sm", centered ? "items-center" : "items-start"].join(" ")}>
        {eyebrow ? <SemanticContent as="p" data-slot="card-eyebrow" className={["text-caption uppercase tracking-label", inverse ? "text-ink-on-inverse-muted" : "text-ink-muted"].join(" ")}>{eyebrow}</SemanticContent> : null}
        {Object.hasOwn(props, "title") ? <SemanticContent as={heading} data-slot="card-title" className={cx(titleSize, "font-display leading-heading text-balance", inverse ? "text-ink-on-inverse" : "text-ink-primary", titleClassName)}>{title}</SemanticContent> : null}
        {description ? <SemanticContent as="p" data-slot="card-description" className={[density === "display" ? "text-body-l" : "text-body", "text-pretty", inverse ? "text-ink-on-inverse-muted" : "text-ink-secondary"].join(" ")}>{description}</SemanticContent> : null}
        {stats ? <SemanticContent as="div" data-slot="card-stats" className="flex flex-wrap items-center gap-sm">{stats}</SemanticContent> : null}
      </SemanticContent>
      {actions ? <SemanticContent as="div" data-slot="card-action" className={["flex shrink-0 flex-wrap items-center gap-sm", centered ? "justify-center" : "justify-start"].join(" ")}>{actions}</SemanticContent> : null}
    </SemanticContent>
  );
}

content.content:
import type { ContentSectionProps } from "@clossys/designer/blocks";
import type { ReactNode } from "react";
import { SemanticContent } from "@clossys/designer/components";
import { mergeUiClasses as cx } from "@clossys/designer/components";
import { SectionHeader } from "../section-header/index.js";

/** Card/CardContent anatomy, with section-owned heading and host-owned body slots. */
export function Content({ header, heading, headingId, eyebrow, description, actions, footnote, takeaway, source, headingLevel = 2, emphasis = "section", size, ground = "base", layout = "stacked", mediaSide, align = "start", media, children, className, style, ...rest }: ContentSectionProps & { header?: ReactNode }) {
  const split = layout !== "stacked";
  const start = layout === "split-start" || layout === "split" && mediaSide === "start";
  const padding = size === "display" ? "py-5xl tablet:py-6xl" : size === "standard" ? "py-4xl tablet:py-5xl" : size === "compact" ? "py-3xl tablet:py-4xl" : "";
  return (
    <SemanticContent as="section" {...rest} data-ds-layer="sections" data-ds-leaf="sections.content" data-ds-fill="shadcn@aria/sections.content" data-slot="card" data-layout={layout} className={cx("flex flex-col gap-xl", padding, className)} style={style}>
      <SemanticContent as="div" className={split ? "grid items-start gap-2xl tablet-lg:grid-cols-2" : "flex flex-col gap-xl"}>
        <SemanticContent as="div" className={["flex min-w-0 flex-col gap-xl", split && start ? "tablet-lg:col-start-2 tablet-lg:row-start-1" : ""].filter(Boolean).join(" ")}>
          {header ?? (heading !== undefined || eyebrow || description || actions ? <SectionHeader id={headingId} level={headingLevel} {...(heading !== undefined ? { title: heading } : {})} eyebrow={eyebrow} description={description} actions={actions} align={align} ground={ground} density={size === "display" || emphasis === "display" ? "display" : "standard"} /> : null)}
          {children !== undefined ? <SemanticContent as="div" data-slot="card-content" className="flex min-w-0 flex-col gap-lg">{children}</SemanticContent> : null}
          {footnote ? <SemanticContent as="p" data-slot="card-footer" className={ground === "inverse" ? "text-caption text-ink-on-inverse-muted" : "text-caption text-ink-secondary"}>{footnote}</SemanticContent> : null}
          {source ? <SemanticContent as="p" data-slot="card-source" className={ground === "inverse" ? "text-caption text-ink-on-inverse-muted" : "text-caption text-ink-muted"}>{source}</SemanticContent> : null}
        </SemanticContent>
        {media ? <SemanticContent as="div" data-slot="card-media" className={["min-w-0", split && start ? "tablet-lg:col-start-1 tablet-lg:row-start-1" : ""].filter(Boolean).join(" ")}>{media}</SemanticContent> : null}
      </SemanticContent>
      {takeaway ? <SemanticContent as="div" data-slot="card-takeaway" className="text-body text-ink-primary">{takeaway}</SemanticContent> : null}
    </SemanticContent>
  );
}

empty-state.content:
import type { EmptyStateProps } from "@clossys/designer/blocks";
import { SemanticContent } from "@clossys/designer/components";
import { mergeUiClasses as cx } from "@clossys/designer/components";
import { SectionHeader } from "../section-header/index.js";

/** The pinned Empty/EmptyHeader/EmptyContent composition; copy and controls stay supplied slots. */
export function EmptyState({ icon, title, description, action, className, ...rest }: EmptyStateProps) {
  return (
    <SemanticContent as="section" {...rest} data-ds-layer="sections" data-ds-leaf="sections.empty-state" data-ds-fill="shadcn@aria/sections.empty-state" data-slot="empty" className={cx("flex min-w-0 flex-1 flex-col items-center justify-center gap-lg p-xl text-center text-balance", className)}>
      <SemanticContent as="div" data-slot="empty-header" className="flex flex-col items-center gap-sm">
        {icon ? <SemanticContent as="div" data-slot="empty-icon" className="flex shrink-0 items-center justify-center text-ink-muted">{icon}</SemanticContent> : null}
        <SectionHeader level={2} title={title} description={description} align="center" density="standard" />
      </SemanticContent>
      {action ? <SemanticContent as="div" data-slot="empty-content" className="flex min-w-0 flex-col items-center gap-md">{action}</SemanticContent> : null}
    </SemanticContent>
  );
}
